   internal Fixture(){Root=Path.Combine(LauncherTestPaths.Root,"aim-retirement-"+Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"steamapps/common/Game"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);Put(E.Config,"{\"vmArgs\":[\"-Xmx12345m\",\"-agentlib:zbNative\",\"-Dother=true\"]}");Put(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture-never-executed");Put(Path.Combine(E.Game,"ZombieBuddy.jar"),"Buddy");Put(Path.Combine(E.Game,"zbNative.dll"),"Buddy native");Put(Path.Combine(E.Workshop,"3809306528/mods/Viewpoint/42/mod.info"),"id=Viewpoint\n");Source=Path.Combine(E.Workshop,ShootClient.Item.ToString());Put(Path.Combine(Source,"mods",ShootClient.Id,"common/mod.info"),"id="+ShootClient.Id+"\nmodversion=3.6.51\n");Put(Path.Combine(Source,"mods",ShootClient.Id,"42/media/java/client/ISeeThem.jar"),"author 3.6.51 fixture");Put(Path.Combine(E.User,"mods/Ordinary/42/mod.info"),"id=Ordinary\n");Put(Path.Combine(E.User,"mods/OrangeShootPresentationUser/42/mod.info"),"id=OrangeShootPresentationUser\n");Calibration=Path.Combine(E.User,"Lua/ShootToThrillCalibration.lua");Put(Calibration,"author calibration = 31.75\r\n");SetDefault();Journal=(string)typeof(PresentationBridge).GetMethod("Journal",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(new PresentationBridge(),new object[]{E});Jar=Path.Combine(Path.GetDirectoryName(PresentationBridge.PropertiesPath(E)),PresentationBridge.Name);Unknown=Path.Combine(E.User,"mods",PresentationBridge.Id,"keep-user.txt");}
