  internal static void Put(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text,new UTF8Encoding(false));}
  static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static string[] Ids(object value){return ((IEnumerable)value).Cast<object>().Select(Convert.ToString).ToArray();}
  static void Check(bool okay,string label){if(!okay)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);}
  static string Retire(PresentationBridge bridge,Engine e){var method=typeof(PresentationBridge).GetMethod("Retire");Check(method!=null,"explicit bridge retirement entry point exists");try{return (string)method.Invoke(bridge,new object[]{e});}catch(TargetInvocationException ex){throw ex.InnerException;}}
  static byte[] WithoutBridge(byte[] original){return Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(original).Replace(" mod = OrangeShootPresentation,\r\n",""));}
  static void Cleanup(){var f=new Fixture();f.OldAddon();byte[] before=File.ReadAllBytes(f.E.Mods),config=File.ReadAllBytes(f.E.Config),author=File.ReadAllBytes(Path.Combine(f.Source,"mods",ShootClient.Id,"42/media/java/client/ISeeThem.jar")),calibration=File.ReadAllBytes(f.Calibration);var bridge=new PresentationBridge();string receipt=Retire(bridge,f.E);Check(File.ReadAllBytes(f.E.Mods).SequenceEqual(WithoutBridge(before)),"retirement removes only exact owned row and preserves BOM maps and custom bytes");Check(!File.Exists(f.Jar)&&!File.Exists(PresentationBridge.PropertiesPath(f.E))&&!File.Exists(f.Journal)&&!File.Exists(Path.Combine(f.E.Data,"aim-fallback.json")),"retirement removes bridge and its private fingerprint/preferences");Check(File.ReadAllText(f.Unknown)=="unknown user bytes"&&File.ReadAllBytes(f.Calibration).SequenceEqual(calibration)&&File.ReadAllBytes(f.E.Config).SequenceEqual(config)&&File.ReadAllBytes(Path.Combine(f.Source,"mods",ShootClient.Id,"42/media/java/client/ISeeThem.jar")).SequenceEqual(author),"retirement preserves author JAR calibration launch arguments and unknown files");Check(Directory.Exists(bridge.LastBackup)&&Directory.GetFiles(bridge.LastBackup).Any(p=>File.ReadAllText(p).Contains("old-private-fingerprint"))&&receipt.Contains(bridge.LastBackup),"cleanup receipt identifies recoverable edited bridge bytes");Retire(bridge,f.E);Check(File.ReadAllBytes(f.E.Mods).SequenceEqual(WithoutBridge(before)),"repeated retirement is idempotent");}
  static void Locked(){var f=new Fixture();f.OldAddon();var bridge=new PresentationBridge();using(var locked=new FileStream(f.Jar,FileMode.Open,FileAccess.Read,FileShare.None)){string result=Retire(bridge,f.E);Check(!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id)&&File.Exists(f.Jar),"exclusive loaded JAR lock cannot prevent detaching default row");Check(result.Contains(f.Jar)&&result.Contains("待")&&Directory.Exists(bridge.LastBackup),"locked cleanup reports exact pending path and a receipt");}Retire(bridge,f.E);Check(!File.Exists(f.Jar),"later explicit cleanup retires the previously locked JAR");}
  static void BaseLocked(){foreach(string target in new[]{"direct","base","all"}){var f=new Fixture();f.OldAddon();using(var locked=new FileStream(f.Jar,FileMode.Open,FileAccess.Read,FileShare.None)){string result;if(target=="direct"){result=f.E.Switch(false,false);Check(Directory.Exists(f.E.LastBackup),"base uninstall retains existing base backup flow");}else using(var c=new ModernController(f.E.Game,f.E.User,f.E.Data,true)){result=Convert.ToString(D(c.Execute("componentsAction",new Dictionary<string,object>{{"component",target},{"operation","uninstall"},{"confirmed",true}}))["message"]);var history=((IEnumerable)D(c.Execute("taskGet",null))["history"]).Cast<object>().Select(D).ToArray();Check((string)history[0]["status"]=="partial","locked bridge leaves modern "+target+" uninstall honestly partial");}Check(result.Contains("[待清理]")&&result.Contains(f.Jar)&&result.Contains("退役收据")&&!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id),"base uninstall propagates exact pending bridge file and recovery receipt: "+target);}}}
  static void BaseFailure(){foreach(string kind in new[]{"read","cancel"}){var f=new Fixture();f.OldAddon();var token=new CancellationToken(true);if(kind=="cancel")f.E.Progress=(v,text)=>{if(text=="检查已下载模组与光影预设")throw new OperationCanceledException("fixture cancellation after retirement",token);};using(var jarLock=new FileStream(f.Jar,FileMode.Open,FileAccess.Read,FileShare.None))using(var loaderLock=kind=="read"?new FileStream(Path.Combine(f.E.Game,"ZombieBuddy.jar"),FileMode.Open,FileAccess.Read,FileShare.None):null){Exception failure=null;try{f.E.Switch(false,false);}catch(Exception ex){failure=ex;}Check(failure!=null&&failure.Message.Contains("[待清理]")&&failure.Message.Contains(f.Jar)&&failure.Message.Contains("退役收据")&&failure.Message.Contains(kind=="read"?"ZombieBuddy.jar":"fixture cancellation after retirement"),"base uninstall later "+kind+" failure preserves original error and earlier cleanup receipt");Check(kind!="cancel"||failure is OperationCanceledException&&((OperationCanceledException)failure).CancellationToken==token,"base uninstall preserves cancellation exception type and token");Check(!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id)&&File.Exists(f.Jar),"failed base uninstall keeps retirement detached and exact locked file pending: "+kind);}}}
  static void Compatibility(){var f=new Fixture();f.OldAddon();string result=new PresentationBridge().Enable(f.E,Path.Combine(f.Root,"missing-author"));Check(!File.Exists(f.Jar)&&!File.Exists(Path.Combine(f.E.Data,"aim-fallback.json"))&&!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id)&&result.Contains("退役"),"obsolete Enable cleans old layer without validating or deploying against author files");using(var c=new ModernController(f.E.Game,f.E.User,f.E.Data,true)){f.OldAddon();c.Execute("reticleSave",new Dictionary<string,object>{{"startNative",false},{"keyText","INVALID"}});Check(!File.Exists(f.Jar)&&!File.Exists(Path.Combine(f.E.Data,"aim-fallback.json")),"obsolete reticleSave cannot persist private preferences or recreate bridge");var state=D(c.Execute("reticleGet",null));Check(state.ContainsKey("retired")&&(bool)state["retired"],"obsolete reticleGet reports retired feature without reading malformed private settings");}}
  static void Session(){foreach(string kind in new[]{"save","server","edited"}){var f=new Fixture();f.OldAddon();byte[] original=File.ReadAllBytes(f.E.Mods),calibration=File.ReadAllBytes(f.Calibration);LaunchProfiles.Stage(f.E,kind=="save"?new ProfileLaunchRequest{Kind="save",Mode="Sandbox",Save="Fixture"}:new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=16261,Username="fixture"});if(kind=="edited")File.AppendAllText(f.E.Mods,"\r\ncustom-player-edit\r\n");byte[] applied=File.ReadAllBytes(f.E.Mods);Retire(new PresentationBridge(),f.E);LaunchProfiles.Recover(f.E,true);Check(!LaunchProfiles.Pending(f.E)&&!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id),"session recovery cannot resurrect retired aiming bridge: "+kind);Check(kind=="edited"?File.ReadAllText(f.E.Mods).Contains("custom-player-edit")&&!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains("Ordinary"):File.ReadAllBytes(f.E.Mods).SequenceEqual(WithoutBridge(original)),"session retirement preserves "+(kind=="edited"?"player-edited current default":"original ordinary mods BOM maps and custom bytes")+": "+kind);Check(File.ReadAllBytes(f.Calibration).SequenceEqual(calibration),"session cleanup preserves author calibration: "+kind);}}
  static void Retained(){var f=new Fixture();f.OldAddon();Check(!LaunchProfiles.Retained(f.E).Contains(PresentationBridge.Id)&&LaunchProfiles.Retained(f.E).Contains(ShootClient.Id),"server launch retains author shooter and excludes retired bridge");}
  static void Direct(){var f=new Fixture();f.OldAddon();byte[] original=File.ReadAllBytes(f.E.Mods);new ShootClient().Enable(f.E,f.Source);Check(!File.Exists(f.Jar)&&File.ReadAllBytes(f.E.Mods).SequenceEqual(WithoutBridge(original)),"direct gun enable cleans bridge while preserving authored default bytes");f.OldAddon();var live=new Engine(f.E.Game,f.E.User,f.E.Data,false,SteamLaunchOptions.Unavailable,name=>{throw new Exception("retirement must not enumerate or stop processes");});Retire(new PresentationBridge(),live);Check(!File.Exists(f.Jar),"retirement does not inspect or require stopping runtime processes");}
  static void Legacy(){var f=new Fixture();string jar=Path.Combine(f.E.Game,PresentationBridge.Name),props=Path.Combine(f.E.Game,PresentationBridge.ConfigName);Put(jar,"old owned javaagent");Put(props,"old private fingerprint");Put(f.Journal,"{\"jarHash\":\"old\",\"propertiesHash\":\"old\"}");Put(f.E.Config,"{\"vmArgs\":[\"-Xmx12345m\",\"-agentlib:zbNative\",\"-javaagent:OrangeShootPresentation.jar\",\"-Dother=true\"]}");using(var locked=new FileStream(jar,FileMode.Open,FileAccess.Read,FileShare.None)){string receipt=Retire(new PresentationBridge(),f.E);Check(!File.ReadAllText(f.E.Config).Contains("-javaagent:OrangeShootPresentation.jar")&&File.ReadAllText(f.E.Config).Contains("-Xmx12345m")&&File.ReadAllText(f.E.Config).Contains("-agentlib:zbNative")&&receipt.Contains(jar),"legacy loaded agent lock still detaches only its own startup argument");}Retire(new PresentationBridge(),f.E);Check(!File.Exists(jar)&&!File.Exists(props)&&!File.Exists(f.Journal),"legacy pending cleanup keeps enough ownership evidence to remove its locked JAR on retry");Put(jar,"unknown standalone file");string result=new LegacyPresentationBridge().Enable(f.E,Path.Combine(f.Root,"missing-author"));Check(File.ReadAllText(jar)=="unknown standalone file"&&result.Contains("退役"),"obsolete legacy Enable never deploys or overwrites unknown standalone file");}
  static void LegacyOptions(){foreach(string variant in new[]{"name","quoted","relative","absolute"}){var f=new Fixture();string jar=Path.Combine(f.E.Game,PresentationBridge.Name),props=Path.Combine(f.E.Game,PresentationBridge.ConfigName);Put(jar,"old owned javaagent");Put(props,"legacy private settings");Put(f.Journal,"{\"jarHash\":\"old\",\"propertiesHash\":\"old\"}");string owned=variant=="name"?PresentationBridge.Name:variant=="quoted"?"\""+jar+"\"":variant=="relative"?".\\"+PresentationBridge.Name:jar.Replace('\\','/');string other=Path.Combine(f.Root,"foreign",PresentationBridge.Name);Put(other,"foreign same-name agent");string[] keep={"-Xmx12345m","-agentlib:zbNative","-javaagent:ISeeThem.jar=author-options","-javaagent:"+other+"=foreign-options","-javaagent:OrangeShootPresentation.jar.user=lookalike-options"};Put(f.E.Config,Json.Serialize(new{vmArgs=keep.Concat(new[]{"-javaagent:"+owned+"=legacy-options"}).ToArray()}));Retire(new PresentationBridge(),f.E);var cfg=D(Json.DeserializeObject(File.ReadAllText(f.E.Config)));Check(Ids(cfg["vmArgs"]).SequenceEqual(keep)&&!File.Exists(jar)&&!File.Exists(props)&&!File.Exists(f.Journal),"legacy options retirement detaches only exact owned agent before deleting files: "+variant);Check(File.ReadAllText(other)=="foreign same-name agent","legacy options retirement preserves foreign same-name agent bytes: "+variant);}}
  static void Status(){var f=new Fixture();f.OldAddon();byte[] original=File.ReadAllBytes(f.E.Mods);var card=ComponentEvidence.Decorate(f.E,"shoot",new{configured=true});Check(card.ContainsKey("bridgeRetirementNeeded")&&(bool)card["bridgeRetirementNeeded"]&&(bool)card["needsReapply"],"existing bridge advertises explicit gun reapply cleanup");Check(File.ReadAllBytes(f.E.Mods).SequenceEqual(original)&&File.Exists(f.Jar),"status evidence never cleans another user's game on read");}
  static void Modern(){foreach(string operation in new[]{"install","update"}){var f=new Fixture();f.OldAddon();using(var c=new ModernController(f.E.Game,f.E.User,f.E.Data,true,(e,ids,p,t,u)=>new Dictionary<ulong,string>{{ShootClient.Item,f.Source}})){var result=D(c.Execute("componentsAction",new Dictionary<string,object>{{"component","shoot"},{"operation",operation}}));Check(!Convert.ToString(result["message"]).Contains("[失败]")&&ShootClient.Enabled(f.E)&&!File.Exists(f.Jar)&&!File.Exists(Path.Combine(f.E.Data,"aim-fallback.json")),"gun "+operation+" preserves author component and retires old bridge without preflight or fingerprint settings");}}}
  static void UpdateFailure(){foreach(string target in new[]{"shoot","base"}){var f=new Fixture();f.OldAddon();using(var locked=new FileStream(f.Jar,FileMode.Open,FileAccess.Read,FileShare.None))using(var c=new ModernController(f.E.Game,f.E.User,f.E.Data,true,(e,ids,p,t,u)=>{throw new Exception("fixture download fails after retirement");})){string result=Convert.ToString(D(c.Execute("componentsAction",new Dictionary<string,object>{{"component",target},{"operation","update"}}))["message"]);Check(result.Contains("[失败]")&&result.Contains("fixture download fails after retirement")&&result.Contains("[待清理]")&&result.Contains(f.Jar)&&result.Contains("退役收据"),"update failure preserves earlier cleanup receipt and exact pending path: "+target);Check(!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id)&&File.Exists(f.Jar),"failed update keeps retired row detached without hiding pending physical cleanup: "+target);}}}
  static void Lease(){var f=new Fixture();f.OldAddon();using(var started=new ManualResetEventSlim())using(var done=new ManualResetEventSlim()){Exception error=null;var worker=new Thread(()=>{started.Set();try{Retire(new PresentationBridge(),f.E);}catch(Exception ex){error=ex;}finally{done.Set();}});bool waited;using(PlayProfileTransaction.Lock(f.E)){worker.Start();Check(started.Wait(5000),"retirement worker enters shared lease boundary");waited=!done.Wait(200);}Check(worker.Join(6000),"retirement worker completes after lease release");if(error!=null)throw error;Check(waited,"retirement serializes with default writers and session cleanup");}}
  static void Profiles(){var f=new Fixture();f.OldAddon();var list=D(ModConfigurations.List(f.E));Check(!Ids(list["activeMods"]).Contains(PresentationBridge.Id)&&Ids(list["activeMods"]).Contains("OrangeShootPresentationUser"),"named profile seeds exclude exact retired ID only");var saved=D(ModConfigurations.Save(f.E,new Dictionary<string,object>{{"id",""},{"name","Legacy draft"},{"stamp",list["stamp"]},{"mods",new[]{"Ordinary",PresentationBridge.Id,"OrangeShootPresentationUser"}}}));Check(!Ids(saved["mods"]).Contains(PresentationBridge.Id),"named profile save cannot persist retired bridge ID");string store=Directory.GetFiles(Path.Combine(f.E.Data,"mod-profiles"),"*.json").Single();File.WriteAllText(store,File.ReadAllText(store).Replace("\"Ordinary\"","\"Ordinary\",\"OrangeShootPresentation\""));byte[] profileBytes=File.ReadAllBytes(store);ModConfigurations.List(f.E);ModConfigurations.Read(f.E,(string)saved["id"]);Check(File.ReadAllBytes(store).SequenceEqual(profileBytes),"reading old named profiles does not rewrite their store");Retire(new PresentationBridge(),f.E);ModConfigurations.Activate(f.E,(string)saved["id"],(string)D(ModConfigurations.List(f.E))["stamp"],true);Check(!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id)&&SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains("OrangeShootPresentationUser"),"activation ignores retired exact ID in old persisted profiles");}
  static void Play(){var f=new Fixture();f.OldAddon();Put(f.E.Config,"{\"vmArgs\":[\"-Xmx2g\",\"-agentlib:zbNative\"]}");var service=new PlayProfiles(f.E);var captured=D(service.Capture(new Dictionary<string,object>{{"stamp",D(service.List())["stamp"]},{"name","Old play profile"},{"targetKind","normal"},{"targetId",""}}));var profile=D(captured["profile"]);string store=(string)typeof(PlayProfiles).GetField("file",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(service);File.WriteAllText(store,File.ReadAllText(store).Replace("\"Ordinary\"","\"Ordinary\",\"OrangeShootPresentation\""));byte[] bytes=File.ReadAllBytes(store);Retire(new PresentationBridge(),f.E);var preview=D(service.Preview((string)profile["id"],(string)D(service.List())["stamp"]));Check(Convert.ToBoolean(preview["canApply"]),"old stored play profile remains applicable after retired files are removed");service.Apply((string)profile["id"],(string)preview["previewStamp"],true);Check(!SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains(PresentationBridge.Id)&&SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).Contains("OrangeShootPresentationUser"),"old play profile apply never resurrects retired exact ID");Check(File.ReadAllBytes(store).SequenceEqual(bytes),"old play profile read preview and apply do not rewrite stored profile bytes");}
  public static void Run(){Cleanup();Locked();BaseLocked();BaseFailure();Compatibility();Session();Retained();Direct();Legacy();LegacyOptions();Status();Modern();UpdateFailure();Lease();Profiles();Play();}
  [STAThread]public static int Main(string[] args){try{if(args.Length==0)Run();else switch(args[0]){case "cleanup":Cleanup();break;case "locked":Locked();break;case "base-locked":BaseLocked();break;case "base-fails":BaseFailure();break;case "compatibility":Compatibility();break;case "session":Session();break;case "retained":Retained();break;case "direct":Direct();break;case "legacy":Legacy();break;case "legacy-options":LegacyOptions();break;case "status":Status();break;case "modern":Modern();break;case "update-fails":UpdateFailure();break;case "lease":Lease();break;case "profiles":Profiles();break;case "play":Play();break;default:throw new Exception("Unknown case");}Console.WriteLine("AIM BRIDGE RETIREMENT REGRESSIONS PASSED");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
